await judge(
  {
    user_claim: "host fuse mounts should be /run/mount/threetched-fs and /run/mount/3tched-fs; 2 mounts inside container from seed systemd service at boot; socket mounted to container as incus mount defined on template for future provisioning with right perms as shared socket; persistent Cozo image NOT losetup loop, added INSIDE container via 'incus exec <container> btrfs device add <btrfs partition>'; image has 2 partitions: ext4 personal/RocksDB storage + btrfs partition added to ro seed to make rw rootfs, plus 2nd partition as upgrade overlay",
    repo_evidence: {
      host_fstab_fragment: "deploy/host-fuse/3tchedfs.fstab: 3tchedFS /run/mounts/3tchedFS, threetched /run/mounts/threetched (fuse.3tchedFS, noauto)",
      host_runit_mount: "deploy/runit/threetched-fs/run: mountpoint=/run/mount/3tchedFS",
      container_fstab_check: "deploy/scripts/bind-instance-root.sh: expects 3tchedFS at /run/mount/3tchedfs and threetched at /run/mount/threetched",
      identity_image_mounts: "deploy/runit/libexec-3tched/op-identity-image: /run/mount/3tchedfs owner guest:3tchedfs.service fuse.3tchedFS per-start",
      lungs_profile: "3tched-lungs profile: lungs-socket-dir /run/opdbus/lungs (ro bind) + runtime-run /run tmpfs; op-identity-root GUEST_LUNGS_SOCKET=/run/opdbus/lungs/lungs.sock, never bind host entire /run",
      egress_template: "deploy/config/agents/conf/op-identity-egress.socket: conditional on OP_EGRESS_UNIX_SOCKET container-local path; proxy must support HTTP + HTTPS CONNECT",
      btrfs_helper: "crates/op-network/src/btrfs.rs: device-add helper exists; verify_unmounted_source rejects stale/shared-pool sources",
      old_template: "deploy/config/identities/container-template.json attach: losetup + mount fstorage.img; Incus disk bind to /opt/run-mounts/persist; Do NOT btrfs device add onto Incus pool"
    }
  },
  {
    host_mount_canonical: {type: "choice", instructions: "Which host mount path pair is canonical for the two FUSE views?", criteria: {"run_mount_dash_fs": "user-proposed /run/mount/threetched-fs + /run/mount/3tched-fs", "run_mounts_plural": "/run/mounts/3tchedFS + /run/mounts/threetched from deploy/host-fuse/3tchedfs.fstab", "run_mount_singular_caps": "/run/mount/3tchedFS single-view host path", "run_mount_3tchedfs": "/run/mount/3tchedfs guest-oriented path"}},
    container_mount_canonical: {type: "choice", instructions: "Which in-container FUSE mount path pair is canonical?", criteria: {"seed_service_pair": "/run/mount/3tchedfs + /run/mount/threetched from bind-instance-root + op-identity-image guest service", "host_mirror_pair": "mirror host /run/mounts/* paths inside container", "single_mount": "single /run/mount/3tchedFS only"}},
    socket_approach: {type: "choice", instructions: "Which socket approach matches template + perms + shared requirement?", criteria: {"lungs_dir_ro": "keep 3tched-lungs profile lungs-socket-dir ro bind /run/opdbus/lungs with lungs.sock, fix /run tmpfs shadowing", "egress_socket": "op-identity-egress.socket conditional on OP_EGRESS_UNIX_SOCKET per-identity HTTP CONNECT proxy socket", "both_sockets": "both: lungs dir for identity/method calls + per-identity egress proxy socket for internet"}},
    persistent_image_method: {type: "choice", instructions: "Which persistent-image method matches user intent + storage safety?", criteria: {"in_container_device_add": "no host losetup loop; btrfs device add executed INSIDE container via incus exec onto btrfs partition; 2-partition image ext4 personal + btrfs seed-add + upgrade overlay", "host_losetup_bind": "legacy host losetup + Incus disk bind to /opt/run-mounts/persist per container-template.json", "pool_subvolume": "plain Incus pool subvolume, no separate image/device-add"}},
    nic_removal_safe: {type: "bool", instructions: "Is removing chatbot NIC safe only if socket-then-network egress replacement is ready first?", criteria: {true: "safe only with replacement proxy/socket ready", false: "safe to remove NIC immediately"}}
  }
)

